import argparse
import os
import sys
import json
import hashlib
import sqlite3
import datetime
import re
from http.server import HTTPServer, BaseHTTPRequestHandler
import urllib.parse

def get_hash(data):
    return hashlib.sha256(data.encode()).hexdigest()

class BasicCard:
    def __init__(self, deck_name, file_path, line_start, line_end, question, answer):
        self.deck_name, self.file_path, self.line_start, self.line_end = deck_name, file_path, line_start, line_end
        self.question, self.answer = question, answer
        self.hash = self.compute_hash()
    def compute_hash(self):
        content = {"basic": {"question": self.question, "answer": self.answer}}
        return hashlib.sha256(json.dumps(content, separators=(',', ':'), sort_keys=True).encode()).hexdigest()
    def to_dict(self, perf=None):
        return {"hash": self.hash, "familyHash": None, "deckName": self.deck_name,
                "location": {"filePath": self.file_path, "lineStart": self.line_start, "lineEnd": self.line_end},
                "content": {"basic": {"question": self.question, "answer": self.answer}},
                "performance": self.perf_to_dict(perf)}
    def perf_to_dict(self, perf):
        if not perf: return None
        return {"addedAt": perf[1], "lastReviewedAt": perf[2], "stability": perf[3], "difficulty": perf[4],
                "intervalRaw": perf[5], "intervalDays": perf[6], "dueDate": perf[7], "reviewCount": perf[8]}

class ClozeCard:
    def __init__(self, deck_name, file_path, line_start, line_end, text, start, end, family_hash):
        self.deck_name, self.file_path, self.line_start, self.line_end = deck_name, file_path, line_start, line_end
        self.text, self.start, self.end, self.family_hash = text, start, end, family_hash
        self.hash = self.compute_hash()
    def compute_hash(self):
        content = {"cloze": {"text": self.text, "start": self.start, "end": self.end}}
        return hashlib.sha256(json.dumps(content, separators=(',', ':'), sort_keys=True).encode()).hexdigest()
    def to_dict(self, perf=None):
        return {"hash": self.hash, "familyHash": self.family_hash, "deckName": self.deck_name,
                "location": {"filePath": self.file_path, "lineStart": self.line_start, "lineEnd": self.line_end},
                "content": {"cloze": {"text": self.text, "start": self.start, "end": self.end}},
                "performance": self.perf_to_dict(perf)}
    def perf_to_dict(self, perf):
        if not perf: return None
        return {"addedAt": perf[1], "lastReviewedAt": perf[2], "stability": perf[3], "difficulty": perf[4],
                "intervalRaw": perf[5], "intervalDays": perf[6], "dueDate": perf[7], "reviewCount": perf[8]}

def parse_directory(directory):
    cards = []
    directory = os.path.abspath(directory)
    if not os.path.isdir(directory):
        print(f"hashcards: error: directory does not exist.")
        sys.exit(1)
    for filename in sorted(os.listdir(directory)):
        if filename.endswith(".md"):
            path = os.path.join(directory, filename)
            deck_name = os.path.splitext(filename)[0]
            with open(path, 'r') as f: lines = f.readlines()
            card_starts = [i for i, line in enumerate(lines) if line.startswith("Q:") or line.startswith("C:")]
            for i, start in enumerate(card_starts):
                end = card_starts[i+1] if i+1 < len(card_starts) else len(lines)
                card_lines = lines[start:end]
                if card_lines[0].startswith("Q:"):
                    q, a, in_a = [card_lines[0][2:].strip()], [], False
                    for cl in card_lines[1:]:
                        if cl.startswith("A:"): in_a, a = True, [cl[2:].strip()]
                        elif in_a: a.append(cl.rstrip('\n'))
                        else: q.append(cl.rstrip('\n'))
                    cards.append(BasicCard(deck_name, path, start, end, "\n".join(q).strip(), "\n".join(a).strip()))
                elif card_lines[0].startswith("C:"):
                    full_text = "\n".join([card_lines[0][2:].strip()] + [cl.rstrip('\n') for cl in card_lines[1:]]).strip()
                    family_hash = hashlib.sha256(full_text.encode()).hexdigest()
                    text, last_idx, clozes = "", 0, []
                    for m in re.finditer(r'\[(.*?)\]', full_text):
                        text += full_text[last_idx:m.start()]
                        s_pos = len(text)
                        text += m.group(1)
                        clozes.append((s_pos, s_pos + len(m.group(1)) - 1))
                        last_idx = m.end()
                    text += full_text[last_idx:]
                    for s_pos, e_pos in clozes:
                        cards.append(ClozeCard(deck_name, path, start, end, text, s_pos, e_pos, family_hash))
    return cards

def init_db(directory):
    db_path = os.path.join(directory, "hashcards.db")
    conn = sqlite3.connect(db_path)
    cur = conn.cursor()
    cur.execute("CREATE TABLE IF NOT EXISTS cards (card_hash TEXT PRIMARY KEY, added_at TEXT NOT NULL, last_reviewed_at TEXT, stability REAL, difficulty REAL, interval_raw REAL, interval_days INTEGER, due_date TEXT, review_count INTEGER NOT NULL)")
    cur.execute("CREATE TABLE IF NOT EXISTS sessions (session_id INTEGER PRIMARY KEY AUTOINCREMENT, started_at TEXT NOT NULL, ended_at TEXT NOT NULL)")
    cur.execute("CREATE TABLE IF NOT EXISTS reviews (review_id INTEGER PRIMARY KEY AUTOINCREMENT, session_id INTEGER NOT NULL, card_hash TEXT NOT NULL, reviewed_at TEXT NOT NULL, grade TEXT NOT NULL, stability REAL NOT NULL, difficulty REAL NOT NULL, interval_raw REAL NOT NULL, interval_days INTEGER NOT NULL, due_date TEXT NOT NULL)")
    conn.commit()
    return conn

def sync_db(directory, cards):
    conn = init_db(directory)
    cur, now = conn.cursor(), datetime.datetime.now().isoformat()
    for card in cards:
        cur.execute("SELECT 1 FROM cards WHERE card_hash = ?", (card.hash,))
        if not cur.fetchone(): cur.execute("INSERT INTO cards (card_hash, added_at, review_count) VALUES (?, ?, ?)", (card.hash, now, 0))
    conn.commit()
    return conn

def cmd_stats(args):
    directory = args.directory or os.getcwd()
    if args.format == "html": print("HTML output is not implemented yet."); return
    cards = parse_directory(directory)
    db_path, db_count = os.path.join(directory, "hashcards.db"), 0
    if os.path.exists(db_path):
        conn = sqlite3.connect(db_path)
        db_count = conn.cursor().execute("SELECT COUNT(*) FROM cards").fetchone()[0]
        conn.close()
    m_path, m_count = os.path.join(directory, "macros.tex"), 0
    if os.path.exists(m_path):
        with open(m_path, 'r') as f: m_count = len([l for l in f if l.strip()])
    print(json.dumps({"cardsInDeckCount": len(cards), "cardsInDbCount": db_count, "texMacroCount": m_count, "cardsReviewedTodayCount": 0}, indent=2))

def cmd_check(args):
    directory = args.directory or os.getcwd()
    sync_db(directory, parse_directory(directory))
    print("ok")

def cmd_export(args):
    directory = args.directory or os.getcwd()
    cards = parse_directory(directory)
    db_path, perf_map = os.path.join(directory, "hashcards.db"), {}
    if os.path.exists(db_path):
        conn = sqlite3.connect(db_path)
        for row in conn.cursor().execute("SELECT * FROM cards").fetchall(): perf_map[row[0]] = row
        conn.close()
    print(json.dumps({"cards": [c.to_dict(perf_map.get(c.hash)) for c in cards], "sessions": []}, indent=2))

def cmd_orphans_list(args):
    directory = args.directory or os.getcwd()
    hashes = {c.hash for c in parse_directory(directory)}
    db_path = os.path.join(directory, "hashcards.db")
    if os.path.exists(db_path):
        conn = sqlite3.connect(db_path)
        for row in conn.cursor().execute("SELECT card_hash FROM cards").fetchall():
            if row[0] not in hashes: print(row[0])
        conn.close()

def cmd_orphans_delete(args):
    directory = args.directory or os.getcwd()
    hashes = list({c.hash for c in parse_directory(directory)})
    db_path = os.path.join(directory, "hashcards.db")
    if os.path.exists(db_path):
        conn = sqlite3.connect(db_path)
        conn.cursor().execute("DELETE FROM cards WHERE card_hash NOT IN (" + ",".join("?"*len(hashes)) + ")", hashes)
        conn.commit()
        conn.close()

def main():
    parser = argparse.ArgumentParser(prog="hashcards")
    sub = parser.add_subparsers(dest="command")
    for cmd in ["stats", "check", "export", "drill"]:
        p = sub.add_parser(cmd)
        p.add_argument("directory", nargs="?")
        if cmd == "stats": p.add_argument("--format", choices=["html", "json"], default="html")
    o_p = sub.add_parser("orphans")
    o_sub = o_p.add_subparsers(dest="subcommand")
    for cmd in ["list", "delete"]:
        p = o_sub.add_parser(cmd)
        p.add_argument("directory", nargs="?")
    args = parser.parse_args()
    if args.command == "stats": cmd_stats(args)
    elif args.command == "check": cmd_check(args)
    elif args.command == "export": cmd_export(args)
    elif args.command == "orphans":
        if args.subcommand == "list": cmd_orphans_list(args)
        elif args.subcommand == "delete": cmd_orphans_delete(args)
    elif args.command == "drill": pass # Stub
    else: parser.print_help()

if __name__ == "__main__": main()
EOF
